static void testAuxAutomation(const File& root,Assets& assets){
    auto p=auxFixture();p.tracks[7].volume=0;p.tracks[7].auxSends[0]={8,.25f,true};p.tracks[8].solo=true;
    auto base=render(p,assets,root,96000,127);auto original=JSON::toString(projectToJson(p));
    for(int slot=0;slot<auxSendCount;++slot){auto test=p;test.tracks[7].auxSends[0].target=-1;test.tracks[7].auxSends[(size_t)slot]={8,.25f,true};auto curve=parameterCurve(automationAuxFirst+slot,7,0,1);test.clips.push_back(curve);auto automated=render(test,assets,root,96000,127);
        expect(automated==render(test,assets,root,96000,511),"each auxiliary target renders sample-exact independently of callback size");
        expect(automated.getRMSLevel(0,3000,3000)<base.getRMSLevel(0,3000,3000)&&automated.getRMSLevel(0,30000,6000)>base.getRMSLevel(0,30000,6000)*2,"send automation reaches the actual pre-fader auxiliary-only Solo path");
        auto e=makeEngine(test,assets,root);AudioBuffer<float> block(2,512);e->seekRequested.store(1);e->render(block.getWritePointer(0),block.getWritePointer(1),512);expect(e->automationReadout[7][(size_t)(122+slot)].load()>.5f&&e->automationReadout[7][(size_t)(122+slot)].load()<.52f,"seek restores every auxiliary curve at the destination slot");
        e->seekRequested.store(3);e->render(block.getWritePointer(0),block.getWritePointer(1),512);expect(e->automationReadout[7][(size_t)(122+slot)].load()==-1,"leaving an auxiliary clip clears live readout and restores the static send level");
        auto loop=test;loop.loop=true;auto le=makeEngine(loop,assets,root);le->seekRequested.store(loop.songLength()-.01);le->render(block.getWritePointer(0),block.getWritePointer(1),512);expect(le->completedLoops.load()>0&&le->automationReadout[7][(size_t)(122+slot)].load()<.02f,"loop wrap evaluates auxiliary automation at its opening value");
    }
    auto automated=p;automated.clips.push_back(parameterCurve(122,7,0,1));auto audio=render(automated,assets,root,96000,127);auto end=base;double error=0;for(int c=0;c<2;++c)for(int n=60000;n<96000;++n)error=jmax(error,(double)std::abs(audio.getSample(c,n)-end.getSample(c,n)));expect(error<1e-6,"after clip end the smoothed send settles to exactly the saved static gain");
    auto file=root.getChildFile("aux-automation.pulse");Project loaded;expect(saveProject(automated,file).wasOk()&&loadProject(file,loaded).wasOk()&&loaded.clips.back().automationTarget==122&&loaded.tracks[7].auxSends==p.tracks[7].auxSends,"schema 35 persists auxiliary curves without replacing static levels or routes");auto invalid=projectToJson(automated);invalid.getDynamicObject()->setProperty("schema",34);auto before=JSON::toString(projectToJson(loaded));expect(projectFromJson(invalid,loaded).failed()&&JSON::toString(projectToJson(loaded))==before,"auxiliary automation mislabeled as schema 34 rejects atomically");auto old=projectToJson(p);old.getDynamicObject()->setProperty("schema",34);expect(projectFromJson(old,loaded).wasOk()&&render(loaded,assets,root,96000,127)==base,"schema 34 send projects migrate without changing their audio");
    auto trim=automated;auto offset=parameterCurve(122,7,.6f,.6f);offset.automationTrim=true;trim.clips.push_back(offset);expect(std::abs(projectAutomationAt(trim,122,7,1)-.7f)<1e-6,"auxiliary Trim layers offset the existing normalized send curve");offset.points={{0,.5f},{2,.5f}};trim.clips.back()=offset;expect(render(trim,assets,root,96000,127)==audio,"neutral auxiliary Trim is sample-exact transparent");
    auto bus=p;bus.tracks[7].auxSends[0]={8,.25f,true};bus.tracks[8].auxSends[0]={9,.3f,false};bus.tracks[8].solo=false;bus.tracks[9].solo=true;bus.clips.push_back(parameterCurve(122,8,0,1));expect(render(bus,assets,root,48000,127).getMagnitude(0,12000,24000)>.001f,"auxiliary automation is available on nested buses as well as source channels");
    auto off=automated;off.tracks[7].auxSends[0].target=-1;expect(render(off,assets,root,48000,127).getMagnitude(0,0,48000)==0,"automating an Off slot never enables a route or leaks dry sound through Solo");
    RenderSettings settings;settings.bits=32;settings.tailSeconds=0;settings.endBeat=4;settings.normalize=false;auto wav=root.getChildFile("aux-automation.wav");expect(renderAudio(automated,assets,root,wav,settings).wasOk(),"auxiliary automation exports through the common callback renderer");String message;auto sample=assets.load(wav,message);bool equal=sample&&sample->audio.getNumSamples()==96000;if(equal)for(int c=0;c<2;++c)for(int n=0;n<96000;++n)equal&=std::abs(sample->audio.getSample(c,n)-audio.getSample(c,n))<1e-6;expect(equal,"float WAV export agrees with live auxiliary automation sample for sample");
    auto operations=JSON::parse(R"([{"op":"add_automation","track":7,"target":"aux.send4.level","targetTrack":7,"beat":0,"length":2,"points":[{"beat":0,"value":0},{"beat":2,"value":1}]}])");Project edited;expect(applyControlEdits(p,operations,edited).wasOk()&&edited.clips.back().automationTarget==125,"MCP accepts discoverable auxiliary keys with stable appended IDs");before=JSON::toString(projectToJson(edited));operations[0].getDynamicObject()->setProperty("targetTrack",-1);expect(applyControlEdits(p,operations,edited).failed()&&JSON::toString(projectToJson(edited))==before,"Master auxiliary automation rejects the entire candidate atomically");
    auto e=makeEngine(automated,assets,root);expect(e->automationWrite.begin({122,7,0,2,0,AutomationWrite::Mode::write,.8f}),"auxiliary destinations accept bounded Write passes");AudioBuffer<float> block(2,512);e->render(block.getWritePointer(0),block.getWritePointer(1),512);expect(e->automationReadout[7][122].load()==.8f,"Write overrides the actual auxiliary destination in the callback");e->automationWrite.interrupt(e->position.load(),true);expect(e->automationWrite.result()&&e->automationWrite.result()->segmentCount==1,"auxiliary passes produce reviewable captured intervals");
    expect(JSON::toString(projectToJson(p))==original,"auxiliary automation tests retain source static settings");
}
